import dlagtm = require( './index' );


// TESTS //

// The function returns a Float64Array...
{
	const DL = new Float64Array( 2 );
	const D = new Float64Array( 3 );
	const DU = new Float64Array( 2 );
	const X = new Float64Array( 6 );
	const B = new Float64Array( 6 );

	dlagtm( 'row-major', 'no-transpose', 3, 2, 1.0, DL, D, DU, X, 2, 0.0, B, 2 ); // $ExpectType Float64Array
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const DL = new Float64Array( 2 );
	const D = new Float64Array( 3 );
	const DU = new Float64Array( 2 );
	const X = new Float64Array( 6 );
	const B = new Float64Array( 6 );

	dlagtm( 5, 'no-transpose', 3, 2, 1.0, DL, D, DU, X, 2, 0.0, B, 2 ); // $ExpectError
	dlagtm( true, 'no-transpose', 3, 2, 1.0, DL, D, DU, X, 2, 0.0, B, 2 ); // $ExpectError
	dlagtm( false, 'no-transpose', 3, 2, 1.0, DL, D, DU, X, 2, 0.0, B, 2 ); // $ExpectError
	dlagtm( null, 'no-transpose', 3, 2, 1.0, DL, D, DU, X, 2, 0.0, B, 2 ); // $ExpectError
	dlagtm( void 0, 'no-transpose', 3, 2, 1.0, DL, D, DU, X, 2, 0.0, B, 2 ); // $ExpectError
	dlagtm( [], 'no-transpose', 3, 2, 1.0, DL, D, DU, X, 2, 0.0, B, 2 ); // $ExpectError
	dlagtm( {}, 'no-transpose', 3, 2, 1.0, DL, D, DU, X, 2, 0.0, B, 2 ); // $ExpectError
	dlagtm( ( x: number ): number => x, 'no-transpose', 3, 2, 1.0, DL, D, DU, X, 2, 0.0, B, 2 ); // $ExpectError
}

